  using(var f=new Fake()){f.filter.action.type=0x5003;var s=ReadinessWfpNative.Observe(f,4,1000);T(s.complete&&s.callout==1&&s.block==0&&s.contextOpaque,"调用驱动单列且未解析上下文不冒充阻断");}
